export interface ConnectorConfig {
  salesforceInstance: string;
  salesforceAccessToken: string;
  hubspotWebhookSecret?: string;
  skipWebsiteSearch?: boolean;
  fetch?: typeof fetch;
}

export interface HubSpotDealPayload {
  dealId: string;
  properties: {
    deal_id: string;
    website_domain: string;
    deal_name: string;
    deal_amount: string;
    deal_close_date: string;
  };
  changeSource: string;
  eventType: string;
  subscriptionId: string;
  portalId: string;
  occurredAt: number;
}

export interface ConnectorResult {
  salesforceAccountId: string;
  created: boolean;
  updated: boolean;
}

function validatePayload(payload: unknown): HubSpotDealPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object');
  }
  const p = payload as Record<string, unknown>;
  if (!p.dealId || typeof p.dealId !== 'string') {
    throw new Error('Missing required field: dealId');
  }
  if (!p.properties || typeof p.properties !== 'object') {
    throw new Error('Missing required field: properties');
  }
  const props = p.properties as Record<string, unknown>;
  const requiredProps = ['deal_id', 'website_domain', 'deal_name', 'deal_amount', 'deal_close_date'];
  for (const field of requiredProps) {
    if (!props[field] || typeof props[field] !== 'string') {
      throw new Error(`Missing required field: properties.${field}`);
    }
  }
  return payload as HubSpotDealPayload;
}

async function soqlQuery(
  instance: string,
  accessToken: string,
  website: string,
  fetchFn: typeof fetch
): Promise<string | null> {
  const encodedWebsite = encodeURIComponent(website);
  const url = `https://${instance}.salesforce.com/services/data/v68.0/query?q=SELECT+Id+FROM+Account+WHERE+Website+=+'${encodedWebsite}'`;
  const response = await fetchFn(url, {
    method: 'GET',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
  });
  if (!response.ok) {
    throw new Error(`SOQL query failed: ${response.status} ${response.statusText} at ${url}`);
  }
  const data = await response.json() as { totalSize: number; records: Array<{ Id: string }> };
  if (data.totalSize > 0 && data.records.length > 0) {
    return data.records[0].Id;
  }
  return null;
}

async function updateAccount(
  instance: string,
  accessToken: string,
  accountId: string,
  fields: Record<string, unknown>,
  fetchFn: typeof fetch
): Promise<void> {
  const url = `https://${instance}.salesforce.com/services/data/v68.0/sobjects/Account/${accountId}`;
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(fields),
  });
  if (!response.ok) {
    throw new Error(`Account update failed: ${response.status} ${response.statusText} at ${url}`);
  }
}

async function upsertAccount(
  instance: string,
  accessToken: string,
  externalId: string,
  fields: Record<string, unknown>,
  fetchFn: typeof fetch
): Promise<{ id: string; created: boolean }> {
  const url = `https://${instance}.salesforce.com/services/data/v68.0/sobjects/Account/HubSpot_Account_ID__c/${externalId}`;
  const response = await fetchFn(url, {
    method: 'PATCH',
    headers: {
      'Authorization': `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(fields),
  });
  if (!response.ok) {
    throw new Error(`Account upsert failed: ${response.status} ${response.statusText} at ${url}`);
  }
  const data = await response.json() as { id: string; success: boolean; errors: string[]; created: boolean };
  if (!data.success) {
    throw new Error(`Account upsert failed: ${data.errors.join(', ')}`);
  }
  return { id: data.id, created: data.created };
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const validated = validatePayload(payload);
  const { dealId, properties } = validated;
  const { deal_id, website_domain, deal_name, deal_amount, deal_close_date } = properties;

  const fetchFn = config.fetch ?? fetch;
  const instance = config.salesforceInstance;
  const accessToken = config.salesforceAccessToken;

  if (!instance) throw new Error('Config missing salesforceInstance');
  if (!accessToken) throw new Error('Config missing salesforceAccessToken');

  const fields = {
    Name: deal_name,
    Website: website_domain,
    Annual_Revenue__c: parseFloat(deal_amount),
    Last_Authorization_Date__c: deal_close_date,
    HubSpot_Account_ID__c: deal_id,
  };

  let accountId: string | null = null;
  let created = false;
  let updated = false;

  if (!config.skipWebsiteSearch) {
    accountId = await soqlQuery(instance, accessToken, website_domain, fetchFn);
  }

  if (accountId) {
    await updateAccount(instance, accessToken, accountId, fields, fetchFn);
    updated = true;
  } else {
    const result = await upsertAccount(instance, accessToken, deal_id, fields, fetchFn);
    accountId = result.id;
    created = result.created;
    if (!result.created) {
      updated = true;
    }
  }

  if (!accountId) {
    throw new Error('Failed to obtain Salesforce Account ID');
  }

  return {
    salesforceAccountId: accountId,
    created,
    updated,
  };
}

import { describe, it, expect, vi } from 'vitest';
