import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      salesforceInstance: 'testinstance',
      salesforceAccessToken: 'test-token',
      skipWebsiteSearch: true,
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotDealPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.salesforceAccountId).toBe('001XX000003DHPzIAO');
    expect(result.created).toBe(false);
    expect(result.updated).toBe(true);
  });
});

describe('handle', () => {
