    const { fetch } = fakeFetch(() => jsonResponse({}, 500));
    const config: ConnectorConfig = {
      salesforceInstance: 'test',
      salesforceAccessToken: 'token',
      fetch,
    };

    await expect(handle({}, config)).rejects.toThrow('Payload must be an object');
    await expect(handle({ dealId: '123' }, config)).rejects.toThrow('Missing required field: properties');
    await expect(handle({ dealId: '123', properties: {} }, config)).rejects.toThrow('Missing required field: properties.deal_id');
  });

  it('performs SOQL query and updates existing account', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/query')) {
        return jsonResponse({ totalSize: 1, records: [{ Id: '001EXISTING' }] });
      }
      if (req.method === 'PATCH' && req.url.includes('/sobjects/Account/001EXISTING')) {
        return jsonResponse(null, 204);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      salesforceInstance: 'testinstance',
      salesforceAccessToken: 'test-token',
      fetch,
    };

    const payload: HubSpotDealPayload = {
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, deal_id: '999' },
