    const result = await handle(payload, config);

    expect(calls.length).toBe(2);
    expect(calls[0].method).toBe('GET');
    expect(calls[0].url).toContain('/query');
    expect(calls[1].method).toBe('PATCH');
    expect(calls[1].url).toContain('/sobjects/Account/001EXISTING');
    expect(result.salesforceAccountId).toBe('001EXISTING');
    expect(result.created).toBe(false);
    expect(result.updated).toBe(true);
  });

  it('performs SOQL query, finds no match, and upserts new account', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, records: [] });
      }
      if (req.method === 'PATCH' && req.url.includes('/HubSpot_Account_ID__c/')) {
        return jsonResponse({ id: '001NEW', success: true, errors: [], created: true });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      salesforceInstance: 'testinstance',
      salesforceAccessToken: 'test-token',
      fetch,
    };

    const payload: HubSpotDealPayload = {
      ...SOURCE_EXAMPLE,
      properties: { ...SOURCE_EXAMPLE.properties, deal_id: '888' },
    };

    const result = await handle(payload, config);

    expect(calls.length).toBe(2);
    expect(calls[0].method).toBe('GET');
    expect(calls[1].method).toBe('PATCH');
    expect(calls[1].url).toContain('/HubSpot_Account_ID__c/888');
    expect(result.salesforceAccountId).toBe('001NEW');
    expect(result.created).toBe(true);
    expect(result.updated).toBe(false);
  });

  it('throws on non-2xx SOQL response', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const config: ConnectorConfig = {
      salesforceInstance: 'test',
      salesforceAccessToken: 'bad-token',
      fetch,
    };

    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealPayload, config)).rejects.toThrow('SOQL query failed: 401 Unauthorized');
  });

  it('throws on non-2xx upsert response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, records: [] });
      }
      return jsonResponse({ error: 'Forbidden' }, 403);
    });

    const config: ConnectorConfig = {
      salesforceInstance: 'test',
      salesforceAccessToken: 'bad-token',
      fetch,
    };

    await expect(handle(SOURCE_EXAMPLE as unknown as HubSpotDealPayload, config)).rejects.toThrow('Account upsert failed: 403 Forbidden');
  });

  it('maps fields correctly in upsert request body', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, records: [] });
      }
      if (req.method === 'PATCH') {
        return jsonResponse({ id: '001NEW', success: true, errors: [], created: true });
      }
      return jsonResponse({ error: 'not found' }, 404);
    });

    const config: ConnectorConfig = {
      salesforceInstance: 'testinstance',
      salesforceAccessToken: 'test-token',
      fetch,
    };

    const payload: HubSpotDealPayload = {
      dealId: '12345',
      properties: {
        deal_id: '12345',
        website_domain: 'example.com',
        deal_name: 'Acme Corp Deal',
        deal_amount: '50000',
        deal_close_date: '2024-01-15',
      },
      changeSource: 'USER_INTERFACE',
      eventType: 'deal.propertiesUpdated',
      subscriptionId: 'sub_abc123',
      portalId: '987654',
      occurredAt: 1705310400000,
    };

    await handle(payload, config);

    const upsertCall = calls.find(c => c.method === 'PATCH' && c.url.includes('/HubSpot_Account_ID__c/'));
    expect(upsertCall).toBeDefined();
    expect(upsertCall!.json).toEqual({
      Name: 'Acme Corp Deal',
      Website: 'example.com',
      Annual_Revenue__c: 50000,
      Last_Authorization_Date__c: '2024-01-15',
      HubSpot_Account_ID__c: '12345',
    });
