  it('uses injected fetch', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.method === 'GET' && req.url.includes('/query')) {
        return jsonResponse({ totalSize: 0, records: [] });
      }
      return jsonResponse({ id: '001NEW', success: true, errors: [], created: true });
